class Solution {
    private int m, n;
    private final int[] dx = {1, -1, 0, 0};
    private final int[] dy = {0, 0, 1, -1};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        m = heights.length;
        n = heights[0].length;
        boolean[][] pac = new boolean[m][n];
        boolean[][] atl = new boolean[m][n];
        Deque<int[]> stack = new ArrayDeque<>();
        for (int j = 0; j < n; j++) {
            pac[0][j] = true;
            stack.push(new int[]{0, j});
        }
        for (int i = 0; i < m; i++) {
            pac[i][0] = true;
            stack.push(new int[]{i, 0});
        }
        flow(heights, pac, stack);
        for (int j = 0; j < n; j++) {
            atl[m - 1][j] = true;
            stack.push(new int[]{m - 1, j});
        }
        for (int i = 0; i < m; i++) {
            atl[i][n - 1] = true;
            stack.push(new int[]{i, n - 1});
        }
        flow(heights, atl, stack);
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (pac[i][j] && atl[i][j]) res.add(Arrays.asList(i, j));
        return res;
    }

    // 从海洋往高处倒灌
    private void flow(int[][] h, boolean[][] seen, Deque<int[]> stack) {
        while (!stack.isEmpty()) {
            int[] c = stack.pop();
            for (int d = 0; d < 4; d++) {
                int x = c[0] + dx[d], y = c[1] + dy[d];
                if (x >= 0 && x < m && y >= 0 && y < n && !seen[x][y]
                        && h[x][y] >= h[c[0]][c[1]]) {
                    seen[x][y] = true;
                    stack.push(new int[]{x, y});
                }
            }
        }
    }
}

