import java.util.*;

class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] indeg = new int[n + 1];
        for (int[] e : edges) indeg[e[1]]++;
        List<Integer> dup = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (indeg[edges[i][1]] == 2) dup.add(i);
        if (!dup.isEmpty()) {
            int last = dup.get(dup.size() - 1), first = dup.get(0);
            if (acyclic(edges, last, n)) return edges[last];
            if (acyclic(edges, first, n)) return edges[first];
        }
        int[] parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;
        for (int[] e : edges) {
            int ru = find(parent, e[0]), rv = find(parent, e[1]);
            if (ru == rv) return new int[]{e[0], e[1]};
            parent[ru] = rv;
        }
        return new int[0];
    }

    private int find(int[] p, int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }

    // 删掉第 skip 条边后是否无环
    private boolean acyclic(int[][] edges, int skip, int n) {
        int[] p = new int[n + 1];
        for (int i = 0; i <= n; i++) p[i] = i;
        for (int i = 0; i < edges.length; i++) {
            if (i == skip) continue;
            int ru = find(p, edges[i][0]), rv = find(p, edges[i][1]);
            if (ru == rv) return false;
            p[ru] = rv;
        }
        return true;
    }
}

