class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] label = new int[n][n];
        List<Integer> area = new ArrayList<>();
        area.add(0);
        int cur = 0;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 1 || label[i][j] != 0) continue;
                cur++;
                label[i][j] = cur;
                Deque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{i, j});
                int size = 0;
                while (!stack.isEmpty()) {
                    int[] c = stack.pop();
                    size++;
                    for (int d = 0; d < 4; d++) {
                        int x = c[0] + dx[d], y = c[1] + dy[d];
                        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1
                                && label[x][y] == 0) {
                            label[x][y] = cur;
                            stack.push(new int[]{x, y});
                        }
                    }
                }
                area.add(size);
            }
        int best = 0;
        for (int a : area) best = Math.max(best, a);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 0) continue;
                Set<Integer> seen = new HashSet<>();
                int total = 1;
                for (int d = 0; d < 4; d++) {
                    int x = i + dx[d], y = j + dy[d];
                    if (x >= 0 && x < n && y >= 0 && y < n && label[x][y] != 0) {
                        int lab = label[x][y];
                        if (seen.add(lab)) total += area.get(lab);
                    }
                }
                if (total > best) best = total;
            }
        return best;
    }
}

