class Solution {
    public int findTheCity(int n, int[][] edges, int distanceThreshold) {
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][n];
        for (int[] row : dist) Arrays.fill(row, INF);
        for (int i = 0; i < n; i++) dist[i][i] = 0;
        for (int[] e : edges) {
            dist[e[0]][e[1]] = e[2];
            dist[e[1]][e[0]] = e[2];
        }
        for (int p = 0; p < n; p++)
            for (int i = 0; i < n; i++) {
                if (dist[i][p] == INF) continue;
                for (int j = 0; j < n; j++) {
                    int nd = dist[i][p] + dist[p][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        int best = n + 1, ans = 0;
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++)
                if (i != j && dist[i][j] <= distanceThreshold) cnt++;
            if (cnt <= best) {
                best = cnt;
                ans = i;
            }
        }
        return ans;
    }
}

